styles:
.b-showcase-mail {
    padding-block: var(--site-space-6);
}

.b-showcase-mail__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-mail__note {
    max-width: 42rem;
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

/* A letter is as tall as its answers; the frame scrolls rather than guessing. */
.b-showcase-mail__letter {
    display: block;
    width: 100%;
    height: 44rem;
    border: 1px solid var(--site-color-border);
    border-radius: var(--site-radius-md);
    background: var(--site-color-surface);
}
